#!/bin/bash
# ============================================================
# mockrobiota mock-3 — Download, Import, and Demultiplex
# QIIME 2 environment: rachis-qiime2-2026.7
# ============================================================
# Dataset: mock-3 (HMP mock community, 21 bacterial strains,
# Even + Staggered abundances, 2 replicates each, 515f/806r
# primers, 16S V4 region). Generated by Dr. Dirk Gevers,
# Broad Institute, 2012.
#
# Known issue (per mockrobiota mock-3 README):
# Barcodes ARE Golay codes, but require reverse-complementing
# on BOTH the mapping file barcodes AND the barcode read file
# to correctly demultiplex.
# ============================================================

set -e  # stop the script if any command fails

# ------------------------------------------------------------
# STEP 1: Set up working directory (UPDATED TO DOWNLOADS)
# ------------------------------------------------------------
mkdir -p /home/alaa/Downloads/mock3
cd /home/alaa/Downloads/mock3

# ------------------------------------------------------------
# STEP 2: Download raw sequencing data
# ------------------------------------------------------------
curl -L -o mock-forward-read.fastq.gz \
    "https://s3-us-west-2.amazonaws.com/mockrobiota/latest/mock-3/mock-forward-read.fastq.gz"

curl -L -o mock-reverse-read.fastq.gz \
    "https://s3-us-west-2.amazonaws.com/mockrobiota/latest/mock-3/mock-reverse-read.fastq.gz"

curl -L -o mock-index-read.fastq.gz \
    "https://s3-us-west-2.amazonaws.com/mockrobiota/latest/mock-3/mock-index-read.fastq.gz"

# ------------------------------------------------------------
# STEP 3: Download sample metadata (barcode-to-sample mapping)
# ------------------------------------------------------------
curl -L -o sample-metadata.tsv \
    "https://raw.githubusercontent.com/caporaso-lab/mockrobiota/master/data/mock-3/sample-metadata.tsv"

# Quick sanity checks (optional, comment out if not needed)
ls -la *.fastq.gz
cat sample-metadata.tsv

# ------------------------------------------------------------
# STEP 4: Activate QIIME 2 environment
# ------------------------------------------------------------
# Note: Ensure 'conda init' has been run in your bashrc for this to work
conda activate rachis-qiime2-2026.7

# ------------------------------------------------------------
# STEP 5: Stage files into QIIME 2's required paired-end
#         import format (exact filenames required)
# ------------------------------------------------------------
mkdir -p emp-paired-end-sequences
cp mock-forward-read.fastq.gz emp-paired-end-sequences/forward.fastq.gz
cp mock-reverse-read.fastq.gz emp-paired-end-sequences/reverse.fastq.gz
cp mock-index-read.fastq.gz emp-paired-end-sequences/barcodes.fastq.gz

# ------------------------------------------------------------
# STEP 6: Import into a QIIME 2 artifact
# ------------------------------------------------------------
qiime tools import \
    --type EMPPairedEndSequences \
    --input-path emp-paired-end-sequences \
    --output-path emp-paired-end-sequences.qza

# ------------------------------------------------------------
# STEP 7: Demultiplex
#         Golay error-correction ON (barcodes ARE Golay codes)
#         Both mapping barcodes AND barcode reads reverse-
#         complemented, per the mock-3 README instructions
# ------------------------------------------------------------
qiime demux emp-paired \
    --i-seqs emp-paired-end-sequences.qza \
    --m-barcodes-file sample-metadata.tsv \
    --m-barcodes-column BarcodeSequence \
    --p-rev-comp-mapping-barcodes \
    --p-rev-comp-barcodes \
    --o-per-sample-sequences demux.qza \
    --o-error-correction-details demux-details.qza

# ------------------------------------------------------------
# STEP 8: Summarize and visualize demultiplexing results
#         (read counts per sample + quality score plots)
# ------------------------------------------------------------
qiime demux summarize \
    --i-data demux.qza \
    --o-visualization demux.qzv

qiime tools view demux.qzv
